$script:UiFontCollection = $null
$script:UiFontMemoryPtr = [IntPtr]::Zero
$script:UiFontFamily = $null

function Initialize-EmbeddedUiFont {
    try {
        $fontBytes = [Convert]::FromBase64String(($script:BundledOnestSemiBoldTtfBase64 -replace '\s', ''))
        $ptr = [Runtime.InteropServices.Marshal]::AllocCoTaskMem($fontBytes.Length)
        [Runtime.InteropServices.Marshal]::Copy($fontBytes, 0, $ptr, $fontBytes.Length)

        $collection = New-Object System.Drawing.Text.PrivateFontCollection
        $collection.AddMemoryFont($ptr, $fontBytes.Length)
        if ($collection.Families.Count -le 0) {
            [Runtime.InteropServices.Marshal]::FreeCoTaskMem($ptr)
            return
        }

        $script:UiFontCollection = $collection
        $script:UiFontMemoryPtr = $ptr
        $script:UiFontFamily = $collection.Families[0]
    }
    catch {
        if ($script:UiFontMemoryPtr -ne [IntPtr]::Zero) {
            try { [Runtime.InteropServices.Marshal]::FreeCoTaskMem($script:UiFontMemoryPtr) } catch {}
            $script:UiFontMemoryPtr = [IntPtr]::Zero
        }
        try { Write-Log ('Не удалось загрузить встроенный шрифт Onest: ' + $_.Exception.Message) } catch {}
    }
}

function New-UiFont {
    param(
        [single] $Size = 9,
        [System.Drawing.FontStyle] $Style = [System.Drawing.FontStyle]::Regular
    )

    if ($script:UiFontFamily) {
        $fontStyle = if ($script:UiFontFamily.IsStyleAvailable($Style)) { $Style } else { [System.Drawing.FontStyle]::Regular }
        return New-Object System.Drawing.Font($script:UiFontFamily, $Size, $fontStyle)
    }

    return New-Object System.Drawing.Font('Segoe UI', $Size, $Style)
}

Initialize-EmbeddedUiFont

